98	<body>
99	  <h1>Phase Tracking</h1>
100	  <p class="sub">Barriers reuse across iterations by flipping phase 0 ↔ 1</p>
101	
102	  <div class="anim-controls">
103	    <button class="anim-btn" id="btnPlay">▶ Animate</button>
104	    <span class="anim-label" id="animLabel"></span>
105	  </div>
106	
107	  <div class="phase-row" id="phaseRow">
108	    <div class="phase-block ph0" data-iter="0"><div class="iter-label">phase = 0</div>Iter 0</div>
109	    <div class="phase-block ph1" data-iter="1"><div class="iter-label">phase = 1</div>Iter 1</div>
110	    <div class="phase-block ph0" data-iter="2"><div class="iter-label">phase = 0</div>Iter 2</div>
111	    <div class="phase-block ph1" data-iter="3"><div class="iter-label">phase = 1</div>Iter 3</div>
112	    <div class="phase-block ph0" data-iter="4"><div class="iter-label">phase = 0</div>Iter 4</div>
113	    <div class="phase-block ph1" data-iter="5"><div class="iter-label">phase = 1</div>Iter 5</div>
114	    <div class="phase-block ph0" data-iter="6"><div class="iter-label">phase = 0</div>Iter 6</div>
115	    <div class="phase-block ph1" data-iter="7"><div class="iter-label">phase = 1</div>Iter 7</div>
116	  </div>
117	
118	  <div class="explain-grid">
119	    <div class="explain-card">
120	      <h3 style="color:#3b82f6;">How It Works</h3>
121	      <div class="ec-body">
122	        Each barrier has a <strong>phase bit</strong> (0 or 1). After all expected arrivals and tracked asynchronous transfers complete, the barrier advances to the next phase and resets — ready for the next iteration. No reinitialization is needed.
123	        <div class="sequence">
124	          <div class="seq-step"><div class="seq-num blue">1</div> Producer reports the arrival and expected transfer bytes (phase 0)</div>
125	          <div class="seq-step"><div class="seq-num green">2</div> Arrivals and transfers finish; the barrier advances to phase 1</div>
126	          <div class="seq-step"><div class="seq-num amber">3</div> <code>try_wait(phase=0)</code> returns; the kernel updates its local parity</div>
127	        </div>
128	      </div>
129	    </div>
130	
131	    <div class="explain-card">
132	      <h3 style="color:#f59e0b;">Why Phase Tracking?</h3>
133	      <div class="ec-body">
134	        In a pipelined kernel, barriers are reused every iteration of the K-loop. Phase tracking solves the problem of <strong>"did this barrier fire for iteration <em>i</em> or iteration <em>i-1</em>?"</strong>
135	        <div style="margin-top:8px;padding:8px 10px;background:#fffbeb;border-radius:6px;font-family:'SF Mono','Fira Code',monospace;font-size:11px;line-height:1.6;">
136	          phase_tma = 0<br>
137	          for k in range(K):<br>
138	          &nbsp;&nbsp;try_wait(tma_bar, <strong>phase_tma</strong>)<br>
139	          &nbsp;&nbsp;phase_tma ^= 1 &nbsp;# flip
140	        </div>
141	      </div>
142	    </div>
143	  </div>
144	
145	
146	<script>
147	(function() {
148	  var blocks = document.querySelectorAll('.phase-block');
149	  var btn = document.getElementById('btnPlay');
150	  var label = document.getElementById('animLabel');
151	  var timer = null;
152	  var step = -1;
153	
154	  function clearAll() {
155	    blocks.forEach(function(b) { b.classList.remove('active'); });
156	    label.textContent = '';
157	  }
158	
159	  function highlight(s) {
160	    clearAll();
161	    if (s >= 0 && s < blocks.length) {
162	      blocks[s].classList.add('active');
163	      var ph = s % 2;
164	      label.textContent = 'Iteration ' + s + '  |  phase = ' + ph;
165	    }
166	  }
167	
168	  function play() {
169	    stop();
170	    step = -1;
171	    btn.textContent = '⏸ Pause';
172	    btn.classList.add('active');
173	    timer = setInterval(function() {
174	      step++;
175	      if (step >= blocks.length) { stop(); return; }
176	      highlight(step);
177	    }, 800);
178	  }
179	
180	  function stop() {
181	    clearInterval(timer);
182	    timer = null;
183	    btn.textContent = '▶ Animate';
184	    btn.classList.remove('active');
185	  }
186	
187	  btn.addEventListener('click', function() {
188	    if (timer) { stop(); clearAll(); }
189	    else play();
190	  });
191	
192	  blocks.forEach(function(b) {
193	    b.addEventListener('click', function() {
194	      stop();
195	      highlight(parseInt(b.dataset.iter));
196	    });
197	  });
198	})();
199	</script>
200	</body>
201	</html>
