class Barrier:
    def __init__(self, expected=1):
        self.parity = 0; self.expected = expected; self.pending = expected; self.tx = 0
    def arrive(self):
        self.pending -= 1; self._c()
    def expect_tx(self, n):
        self.pending -= 1; self.tx += n; self._c()
    def complete_tx(self, n):
        self.tx -= n; self._c()
    def _c(self):
        if self.pending == 0 and self.tx == 0:
            self.parity ^= 1; self.pending = self.expected
    def try_wait(self, p, tag):
        if self.parity == p:
            raise RuntimeError(f"BLOCKED: {tag} waits parity {p} but barrier sits at {self.parity}")
        return self.parity

S = 2; N = 6
full = [Barrier() for _ in range(S)]; empty = [Barrier() for _ in range(S)]
ph_full, ph_empty = 0, 1   # consumer starts 0, producer starts 1 (Step 7 rule)
print("k | stage | C.wait(full,ph) | full after TMA | P.wait(empty,ph) | empty after arrive")
for k in range(N):
    s = k % S
    p = try_empty = empty[s].try_wait(ph_empty, f"P{k}")      # producer: buffer reusable?
    empty_before = empty[s].parity
    full[s].expect_tx(32768); full[s].complete_tx(32768)      # TMA load k -> full[s] flips
    f_after = full[s].parity
    full[s].try_wait(ph_full, f"C{k}")                        # consumer: data ready?
    empty[s].arrive()                                          # consumer returns buffer
    e_after = empty[s].parity
    print(f"{k} |   {s}   |   wait(full[{s}],{ph_full})   |   {f_after}          |  wait(empty[{s}],{ph_empty})  |   {e_after}")
    if s == S - 1:
        ph_full ^= 1; ph_empty ^= 1
print("phase_full over k:", [ (k//S)%2 for k in range(N) ])
print("phase_empty over k:", [ 1-((k//S)%2) for k in range(N) ])
